    fn test_recursive_workspace_patterns_skip_excluded_dirs() {
        let temp = tempdir().expect("tempdir should be created");
        let root = temp.path();

        let real_pkg = root.join("apps/real-app");
        let ignored_pkg = root.join("apps/real-app/node_modules/fake-pkg");
        let dist_pkg = root.join("apps/real-app/dist/generated-pkg");

        fs::create_dir_all(&real_pkg).expect("real package dir should be created");
        fs::create_dir_all(&ignored_pkg).expect("node_modules package dir should be created");
        fs::create_dir_all(&dist_pkg).expect("dist package dir should be created");

        fs::write(
            real_pkg.join("package.json"),
            r#"{ "name": "@demo/real-app" }"#,
        )
        .expect("real package manifest should be written");
        fs::write(
            ignored_pkg.join("package.json"),
            r#"{ "name": "@demo/fake-pkg" }"#,
        )
        .expect("node_modules package manifest should be written");
        fs::write(
            dist_pkg.join("package.json"),
            r#"{ "name": "@demo/generated-pkg" }"#,
        )
        .expect("dist package manifest should be written");

        let packages = Workspace::expand_patterns(
            root,
            &[String::from("apps/**/*")],
            &AnalysisBudget::default(),
        )
        .expect("workspace patterns should expand");

        assert!(
            packages.contains_key("@demo/real-app"),
            "should include the real recursive workspace package"
        );
        assert!(
            !packages.contains_key("@demo/fake-pkg"),
            "should skip node_modules packages"
        );
        assert!(
            !packages.contains_key("@demo/generated-pkg"),
            "should skip dist packages"
        );
    }
}

fn duplicate_package_names_and_distinct_workspace_roots_are_rejected() {
    let temp = tempfile::tempdir().expect("directory");
    for (workspace, package_name) in [("one", "a"), ("two", "b")] {
        let root = temp.path().join(workspace);
        fs::create_dir(&root).expect("root");
        fs::write(
            root.join("package.json"),
            r#"{"name":"root","workspaces":["packages/*"]}"#,
        )
        .expect("workspace");
        let dir = root.join("packages/first");
        cycle(&dir);
        fs::write(
            dir.join("package.json"),
            format!("{{\"name\":\"{package_name}\"}}"),
        )
        .expect("manifest");
    }
    let output = scan(temp.path(), &["one", "two", "--outer", "--json"]);
    assert_eq!(
        output.status.code(),
        Some(2),
        "no silently omitted second workspace"
    );
    assert!(
        String::from_utf8_lossy(&output.stderr).contains("one workspace"),
        "explicit scope diagnostic"
    );
    let duplicate = temp.path().join("one/packages/second");
    cycle(&duplicate);
    fs::write(duplicate.join("package.json"), r#"{"name":"a"}"#).expect("duplicate name");
    let duplicate_result = scan(&temp.path().join("one"), &["--outer", "--json"]);
    assert_eq!(
        duplicate_result.status.code(),
        Some(2),
        "distinct directories cannot share one package graph node"
    );
    assert!(
        String::from_utf8_lossy(&duplicate_result.stderr)
            .contains("duplicate workspace package name"),
        "domain diagnostic"
    );
}

fn test_workspace_external_package() {
    let workspace = create_test_workspace();
    let extractor =
        ImportExtractor::new(vec!["ts".to_owned()], None).with_workspace(Some(workspace));

    let target = extractor
        .resolve_import(Path::new("/app/index.ts"), "react")
        .expect("resolution within budget");
    assert!(
        matches!(&target, ImportTarget::External(name) if name == "react"),
        "should detect react as external, got: {target:?}"
    );
}

fn test_workspace_only_mode_skips_non_workspace_imports() {
    let workspace = create_test_workspace();
    let extractor = ImportExtractor::new(vec!["ts".to_owned()], None)
        .with_workspace(Some(workspace))
        .with_mode(ExtractionMode::WorkspaceOnly);

    let workspace_import = extractor
        .create_import_from_specifier_text(
            "\"@myorg/shared/helpers\"",
            Path::new("/app/index.ts"),
        )
        .expect("valid extraction");
    assert!(
        matches!(
            workspace_import.as_ref().map(|import| &import.target),
            Some(ImportTarget::WorkspacePackage {
                package_name,
                subpath: Some(subpath),
            }) if package_name == "@myorg/shared" && subpath == "helpers"
        ),
        "workspace-only mode should keep workspace imports, got: {workspace_import:?}"
    );

    let relative_import = extractor
        .create_import_from_specifier_text("\"./local-helper\"", Path::new("/app/index.ts"))
        .expect("valid extraction");
    assert!(
        relative_import.is_none(),
        "workspace-only mode should skip relative imports"
    );

    let external_import = extractor
        .create_import_from_specifier_text("\"react\"", Path::new("/app/index.ts"))
        .expect("valid extraction");
    assert!(
        external_import.is_none(),
        "workspace-only mode should skip external imports"
    );
}

fn test_is_workspace_package() {
    let mut packages = HashMap::new();
    let _ = packages.insert("@myorg/utils".to_owned(), PathBuf::from("/pkg/utils"));
    let _ = packages.insert("shared".to_owned(), PathBuf::from("/pkg/shared"));

    let workspace = Workspace {
        root: PathBuf::from("/"),
        format: WorkspaceFormat::Npm,
        packages,
        aliases: HashMap::new(),
    };

    assert!(
        workspace.is_workspace_package("@myorg/utils"),
        "should detect workspace package"
    );
    assert!(
        workspace.is_workspace_package("@myorg/utils/helpers"),
        "should detect workspace package with subpath"
    );
    assert!(
        workspace.is_workspace_package("shared"),
        "should detect simple workspace package"
    );
    assert!(
        !workspace.is_workspace_package("react"),
        "should not match external package"
    );
}

